SELECT [schemaName] COLLATE DATABASE_DEFAULT AS [schemaName],[objectName] COLLATE DATABASE_DEFAULT AS [objectName],[name] COLLATE DATABASE_DEFAULT AS [name],[typeName] COLLATE DATABASE_DEFAULT AS [typeName],[parameter_id],[max_length],[precision],[scale],[is_output] INTO #Expected_parameters FROM OPENJSON(@expected) WITH ([schemaName] nvarchar(4000) '$.schemaName',[objectName] nvarchar(4000) '$.objectName',[name] nvarchar(4000) '$.name',[typeName] nvarchar(4000) '$.typeName',[parameter_id] int '$.parameter_id',[max_length] int '$.max_length',[precision] int '$.precision',[scale] int '$.scale',[is_output] bit '$.is_output');
SELECT [schemaName] COLLATE DATABASE_DEFAULT AS [schemaName],[objectName] COLLATE DATABASE_DEFAULT AS [objectName],[name] COLLATE DATABASE_DEFAULT AS [name],[typeName] COLLATE DATABASE_DEFAULT AS [typeName],[parameter_id],[max_length],[precision],[scale],[is_output] INTO #Actual_parameters FROM (SELECT SCHEMA_NAME(o.schema_id) schemaName,o.name objectName,p.parameter_id,p.name,ty.name typeName,p.max_length,p.precision,p.scale,p.is_output,p.has_default_value FROM sys.parameters p JOIN sys.objects o ON o.object_id=p.object_id JOIN sys.types ty ON ty.user_type_id=p.user_type_id WHERE o.is_ms_shipped=0) actual;
IF EXISTS (SELECT * FROM #Expected_parameters EXCEPT SELECT * FROM #Actual_parameters) OR EXISTS (SELECT * FROM #Actual_parameters EXCEPT SELECT * FROM #Expected_parameters)
BEGIN
 SELECT 'Missing or changed' AS Difference,* FROM (SELECT * FROM #Expected_parameters EXCEPT SELECT * FROM #Actual_parameters) missing;
 SELECT 'Unexpected or changed' AS Difference,* FROM (SELECT * FROM #Actual_parameters EXCEPT SELECT * FROM #Expected_parameters) extra;
 THROW 51001, 'Verify parameters failed.', 1;
END;
DROP TABLE #Expected_parameters; DROP TABLE #Actual_parameters;
PRINT 'PASS parameters';
GO
DECLARE @name nvarchar(517);
DECLARE module_cursor CURSOR LOCAL FAST_FORWARD FOR SELECT QUOTENAME(SCHEMA_NAME(schema_id))+'.'+QUOTENAME(name) FROM sys.objects WHERE type IN('P','V','TR') AND is_ms_shipped=0;
OPEN module_cursor;FETCH NEXT FROM module_cursor INTO @name;
WHILE @@FETCH_STATUS=0
BEGIN
 EXEC sys.sp_refreshsqlmodule @name;
 FETCH NEXT FROM module_cursor INTO @name;
END;
CLOSE module_cursor;DEALLOCATE module_cursor;
PRINT 'PASS all modules refreshed/compiled';
GO
